/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void tmr_update (Tmr tmr, UInt32 tick_count, Boolean use_fiq_tc)
{
	if (use_fiq_tc)
	{
		switch (tmr->timer_base_addr)
		{
			case TMR1_BASE_ADDR:
				TxMR = fiq_get_tc (FIQ_TC_TIMER_1) + tick_count ;
				break ;
			case TMR2_BASE_ADDR:
				TxMR = fiq_get_tc (FIQ_TC_TIMER_2) + tick_count ;
				break ;
		}
	}
	else
	{
		TxMR = TxTC + tick_count ;
	}
				
	TxIR = (1u << tmr->tmr_index) ;
}

